private parseExpression(): AST.ASTNode {
  let expr = this.parseBinaryExpression();

  // Check for match expression
  if (this.check(TokenType.MATCH)) {
    return this.parseMatchExpression(expr);
  }

  // Check for error recovery: expr or error { ... }
  if (this.check(TokenType.OR)) {
    return this.parseErrorRecovery(expr);
  }

  return expr;
}

private parseMatchExpression(discriminant: AST.ASTNode): AST.MatchExpression {
  this.consume(TokenType.MATCH);
  this.consume(TokenType.LBRACE);

  const cases: AST.MatchCase[] = [];

  while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
    const pattern = this.consume(TokenType.IDENTIFIER).value; // Ok, Err, _

    let binding: string | undefined;
    if (this.match(TokenType.LPAREN)) {
      binding = this.consume(TokenType.IDENTIFIER).value;
      this.consume(TokenType.RPAREN);
    }

    this.consume(TokenType.ARROW);

    // Parse body - can be expression or block
    let body: AST.ASTNode;
    if (this.check(TokenType.LBRACE)) {
      body = this.parseBlockStatement();
    } else {
      body = this.parseExpression();
    }

    cases.push({ pattern, binding, body });

    // Optional comma between cases
    this.match(TokenType.COMMA);
  }

  this.consume(TokenType.RBRACE);

  return {
    type: 'MatchExpression',
    discriminant,
    cases,
  };
}

private parseErrorRecovery(expression: AST.ASTNode): AST.ErrorRecovery {
  this.consume(TokenType.OR);
  this.consume(TokenType.ERROR);
  this.consume(TokenType.LBRACE);

  // Parse optional error binding
  let binding = 'e';

  // Parse @context annotation if present
  let contextBlock: AST.ContextBlock = {};
  if (this.check(TokenType.AT)) {
    contextBlock = this.parseContextBlock();
  }

  // Parse error action (usually a return statement or block)
  let errorAction: AST.ASTNode;
  if (this.check(TokenType.RETURN)) {
    errorAction = this.parseReturnStatement();
  } else {
    errorAction = this.parseStatement() || { type: 'BlockStatement', body: [] };
  }

  this.consume(TokenType.RBRACE);

  return {
    type: 'ErrorRecovery',
    binding,
    contextBlock,
    errorAction,
  };
}

private parseContextBlock(): AST.ContextBlock {
  // Expect @context
  this.consume(TokenType.AT);
  const contextToken = this.consume(TokenType.IDENTIFIER);

  if (contextToken.value !== 'context') {
    throw new Error(`Expected @context, got @${contextToken.value}`);
  }

  this.consume(TokenType.LBRACE);

  const context: AST.ContextBlock = {};

  // Parse key-value pairs
  while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
    const keyToken = this.consume(TokenType.IDENTIFIER);
    this.consume(TokenType.COLON);

    // Parse value (simplified - just capture until comma or closing brace)
    const value = this.parseContextValue();

    (context as any)[keyToken.value] = value;

    this.match(TokenType.COMMA);
  }

  this.consume(TokenType.RBRACE);

  return context;
}

private parseContextValue(): any {
  // Simplified context value parsing
  if (this.check(TokenType.STRING)) {
    return this.advance().value;
  }
  if (this.check(TokenType.NUMBER)) {
    return parseFloat(this.advance().value);
  }
  if (this.check(TokenType.BOOLEAN)) {
    return this.advance().value === 'true';
  }
  if (this.check(TokenType.LBRACE)) {
    // Parse object
    this.consume(TokenType.LBRACE);
    const obj: any = {};
    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
      const key = this.consume(TokenType.IDENTIFIER).value;
      this.consume(TokenType.COLON);
      obj[key] = this.parseContextValue();
      this.match(TokenType.COMMA);
    }
    this.consume(TokenType.RBRACE);
    return obj;
  }
  if (this.check(TokenType.LBRACKET)) {
    // Parse array
    this.consume(TokenType.LBRACKET);
    const arr: any[] = [];
    while (!this.check(TokenType.RBRACKET) && !this.isAtEnd()) {
      arr.push(this.parseContextValue());
      this.match(TokenType.COMMA);
    }
    this.consume(TokenType.RBRACKET);
    return arr;
  }

  // Default: identifier or literal
  return this.advance().value;
}

